@lru_cache(maxsize=None)
def get_card(card):
    """card = (rank, suit), e.g. ("10", "♥"). Returns an RGBA PIL image (130x186)."""
    return Image.open(io.BytesIO(base64.b64decode(DATA[card]))).convert("RGBA")
